css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader::before { content: ''; position: absolute; inset: 0; border-radius: 50%; background: repeating-conic-gradient(from 0deg, var(--accent-2) 0 .7deg, transparent .7deg 45deg); }
.loader::after { content: ''; position: absolute; inset: 0; border-radius: 50%; background: repeating-radial-gradient(circle, transparent 0 10.5%, var(--accent) 10.5% 12%); animation: weave calc(var(--loader-speed) * 2.6) linear infinite; }
.loader span { position: absolute; z-index: 2; top: 50%; left: 50%; width: 11%; height: 11%; margin: -5.5% 0 0 -5.5%; border-radius: 50%; background: radial-gradient(circle at 42% 34%, color-mix(in srgb, #fff 30%, var(--accent-2)), color-mix(in srgb, #000 42%, var(--accent-2))); animation: crawl calc(var(--loader-speed) * 2.6) linear infinite; }
@keyframes weave { 0% { clip-path: circle(5% at 50% 50%); } 100% { clip-path: circle(51% at 50% 50%); } }
@keyframes crawl { 0% { transform: rotate(0deg) translateX(calc(var(--loader-size) * .04)); } 100% { transform: rotate(1080deg) translateX(calc(var(--loader-size) * .45)); } }
